import React, { useEffect, useState } from "react";
import './PlaceDetails.css';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

const PlaceDetails = () => {
    const { id } = useParams();
    const [place, setPlace] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    useEffect(() => {
        console.log('Place ID:', id);  // Check if this logs the correct id from the URL
        const fetchPlace = async () => {
            try {
                const response = await axios.get(`/api/places/${id}`);
                setPlace(response.data);
            } catch (error) {
                setError("Place not found or an error occurred.");
            } finally {
                setLoading(false);
            }
        };
    
        fetchPlace();
    }, [id]);

    if (loading) return <div>Loading...</div>;
    if (error) return <div>{error}</div>;

    const goBackToCatalog = () => {
        navigate('/catalog');
    };

    return (
        <div className="place-details">
            <img src={place.image} alt={place.location} className="place-details-img" />
            <div className="place-hero">
                <div className="characteristics">
                    <span className="characteristic">1 characteristic</span>
                    <span className="characteristic">2 characteristic</span>
                </div>
                <h2>{place.name}</h2>
                <p><strong>About: </strong> {place.description}</p>
                <p><strong>Max Visitors: </strong> {place.maxVisitors}</p>
                <p><strong>Location: </strong> {place.location}</p>
                <p className="price">Price: {place.price} UAH/day</p>
            </div>
            <div className="buttons">
                <button className="go-back" onClick={goBackToCatalog}>Return to catalog</button>
                <button className="add-to-cart">Add to cart</button>
            </div>
        </div>
    );
};

export default PlaceDetails;
